import type { StoryPackage, ChoiceOption } from '@kawaijs/ast';
import type { ShareConfig } from './share-meta.js';
import { characterAssetCandidates } from './asset-fallbacks.js';

export type AssetType = 'background' | 'character' | 'audio';

export function defaultAssetResolver(path: string, type: AssetType): string {
  if (
    path.startsWith('http://') ||
    path.startsWith('https://') ||
    path.startsWith('data:') ||
    path.startsWith('/') ||
    path.startsWith('./')
  ) {
    return path;
  }

  if (type === 'background') {
    const clean = path.replace(/^bg[\s_]+/i, '').trim();
    return clean.includes('.') ? `assets/backgrounds/${clean}` : `assets/backgrounds/${clean}.svg`;
  }

  if (type === 'character') {
    const clean = path.replace(/_/g, '/').replace(/\s+/g, '/').trim();
    return clean.includes('.') ? `assets/characters/${clean}` : `assets/characters/${clean}.svg`;
  }

  if (type === 'audio') {
    return path.includes('.') ? `assets/audio/${path}` : `assets/audio/${path}.mp3`;
  }

  return path;
}

/**
 * Preload story assets with bounded concurrency to avoid RAM/network spikes on mobile.
 */
export function preloadStoryAssets(story: StoryPackage, assetResolver: (path: string, type: AssetType) => string = defaultAssetResolver): void {
  if (typeof window === 'undefined') return;

  const bgSet = new Set<string>();
  const charSet = new Set<string>();

  for (const label of Object.values(story.labels)) {
    for (const inst of label) {
      if (inst.type === 'scene' && inst.background) {
        const clean = inst.background.replace(/^bg[\s_]+/i, '').trim();
        bgSet.add(clean);
      } else if (inst.type === 'show') {
        const key = inst.expression ? `${inst.character}/${inst.expression}` : inst.character;
        charSet.add(key);
      }
    }
  }

  const urls: string[] = [];
  for (const bg of bgSet) {
    urls.push(assetResolver(bg, 'background'));
  }
  for (const char of charSet) {
    const candidates = characterAssetCandidates(char, assetResolver);
    if (candidates[0]) urls.push(candidates[0]);
  }

  const saveData = Boolean((navigator as Navigator & { connection?: { saveData?: boolean } }).connection?.saveData);
  const coarse =
    typeof window.matchMedia === 'function' && window.matchMedia('(pointer: coarse)').matches;
  const concurrency = saveData ? 2 : coarse ? 3 : 6;

  let index = 0;
  let active = 0;

  const pump = (): void => {
    while (active < concurrency && index < urls.length) {
      const url = urls[index++]!;
      active++;
      const img = new Image();
      const done = (): void => {
        active--;
        // Drop reference promptly so decode buffers can GC.
        img.onload = null;
        img.onerror = null;
        pump();
      };
      img.onload = done;
      img.onerror = done;
      img.decoding = 'async';
      img.src = url;
    }
  };

  const start = (): void => {
    pump();
  };

  if (typeof window.requestIdleCallback === 'function') {
    window.requestIdleCallback(() => start(), { timeout: 1200 });
  } else {
    setTimeout(start, 0);
  }
}

export interface GalleryItem {
  readonly id: string;
  readonly title: string;
  readonly image: string;
  readonly thumbnail?: string;
  readonly description?: string;
}

export interface MainMenuItem {
  id?: string;
  label: string;
  icon?: string;
  action: 'start' | 'continue' | 'load' | 'gallery' | 'achievements' | 'settings' | 'about' | 'history' | 'quit' | (() => void);
  condition?: () => boolean;
  className?: string;
}

export interface MainMenuOptions {
  /**
   * Whether to display the Start / Main Menu screen before entering the story.
   * Default: true (Ren'Py style)
   */
  enabled?: boolean;
  title?: string;
  subtitle?: string;
  logoUrl?: string;
  backgroundUrl?: string;
  bgmTrack?: string;
  items?: MainMenuItem[];
  galleryItems?: readonly GalleryItem[];
  customFooter?: string;
  onStart?: () => void;
  onOpen?: () => void;
  onClose?: () => void;
  onQuit?: () => void;
}

export interface AudioManagerLike {
  playMusic?(src: string, options?: { fadein?: number; loop?: boolean; volume?: number }): void;
  stopMusic?(options?: { fadeout?: number }): void;
  playSound?(src: string, volume?: number): void;
  stopSound?(): void;
  playVoice?(src: string, volume?: number): void;
  stopVoice?(): void;
  setMusicVolume(val: number): void;
  setSoundVolume(val: number): void;
  setMasterVolume?(val: number): void;
  getMusicVolume?(): number;
  getSoundVolume?(): number;
  destroy?(): void;
}

export interface VirtualCanvasOptions {
  readonly width?: number;
  readonly height?: number;
  readonly scaleMode?: 'contain' | 'cover' | 'stretch';
}

/**
 * Minimal contracts so consumers can replace dialogue / choice presentation
 * without forking DOMRenderer.
 */
export interface DialogueBoxLike {
  readonly el: HTMLElement;
  setTypewriterSpeed(speed: number): void;
  getIsTypewriting(): boolean;
  finishTypewriter(): void;
  render(
    dialogue: {
      speaker?: string;
      speakerDisplayName?: string;
      speakerColor?: string;
      text: string;
    } | null | undefined,
    onComplete?: () => void
  ): void;
  destroy(): void;
}

export interface ChoiceMenuLike {
  readonly el: HTMLElement;
  render(choices: readonly ChoiceOption[] | null | undefined): void;
  hide?(): void;
}

export interface RendererComponentFactories {
  createDialogueBox?: (typewriterSpeed: number) => DialogueBoxLike;
  createChoiceMenu?: (callbacks: { onSelect: (index: number) => void }) => ChoiceMenuLike;
}

export interface RendererFeatureOptions {
  /** Show the bottom quick menu (default: true). */
  quickMenu?: boolean;
  /**
   * After finishing typewriter text, ignore advance clicks for this many ms
   * to prevent accidental double-advance (default: 220).
   */
  advanceDebounceMs?: number;
  /** Horizontal swipe gestures on mobile (default: true). */
  touchGestures?: boolean;
}

export interface DOMRendererOptions {
  container: HTMLElement;
  typewriterSpeed?: number; // ms per character, 0 for instant
  autoDelayMs?: number; // delay before auto-advancing
  assetResolver?: (path: string, type: AssetType) => string;
  mainMenu?: MainMenuOptions;
  audioManager?: AudioManagerLike;
  virtualCanvas?: VirtualCanvasOptions;
  onError?: (error: Error) => void;
  /** Optional factories to replace built-in dialogue / choice UI. */
  components?: RendererComponentFactories;
  features?: RendererFeatureOptions;
  /**
   * Keep `?at=` in the URL in sync with the current user-facing label.
   * Default: false (enabled automatically by mountKawaApp when a deep-link is present).
   */
  syncUrlLabel?: boolean;
  /**
   * Open Graph / Twitter share metadata (updated as the player moves between labels).
   */
  share?: ShareConfig;
  /**
   * Embed / iframe-friendly mode: no main menu chrome, compact UI.
   * Default: false (also auto-detected via `?embed=1` in mountKawaApp).
   */
  embed?: boolean;
}
